const googleTrends = require('google-trends-api');

exports.getInterestOverTime = async (req, res) => {
  const { keyword = 'ReactJS', startTime, endTime } = req.query;

  const now = new Date();
  const defaultStart = new Date(now.getFullYear(), now.getMonth() - 1, now.getDate()); // past month

  try {
    const results = await googleTrends.interestOverTime({
      keyword,
      startTime: startTime ? new Date(startTime) : defaultStart,
      endTime: endTime ? new Date(endTime) : now,
      geo: "",
      granularity: "day"
    });

    const parsed = JSON.parse(results);
    const timelineData = parsed.default.timelineData.map(item => ({
      time: item.formattedTime,
      value: item.value[0]
    }));

    res.json({ keyword, data: timelineData });
  } catch (err) {
    res.status(500).json({ error: 'Failed to fetch trends' });
  }
};
