```jsx
import React, { useState } from 'react';
import axios from 'axios';
import TrendsChart from './components/TrendsChart';

function App() {
  const [data, setData] = useState([]);
  const [keyword, setKeyword] = useState('ReactJS');
  const [loading, setLoading] = useState(false);

  const fetchTrends = async (searchTerm) => {
    setLoading(true);
    try {
      const res = await axios.get(`http://localhost:5000/api/trends?keyword=${encodeURIComponent(searchTerm)}`);
      setData(res.data.data);
      setKeyword(res.data.keyword);
    } catch (e) {
      setData([]);
      alert('Failed to fetch trends');
    }
    setLoading(false);
  };

  React.useEffect(() => {
    fetchTrends(keyword);
    // eslint-disable-next-line
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    fetchTrends(keyword);
  };

  return (
    <div style={{ maxWidth: 800, margin: '2rem auto' }}>
      <form onSubmit={handleSubmit}>
        <input
          value={keyword}
          onChange={e => setKeyword(e.target.value)}
          placeholder="Enter keyword"
          style={{ padding: '0.5rem' }}
        />
        <button type="submit" style={{ marginLeft: 10, padding: '0.5rem 1rem' }}>
          Search
        </button>
      </form>
      {loading ? <p>Loading...</p> : <TrendsChart data={data} keyword={keyword} />}
    </div>
  );
}

export default App;
```
